#include <components/nif/niffile.hpp>
#include <components/nifbullet/actorragdoll.hpp>
#include <fstream>
#include <iostream>
#include <iomanip>
#include <stdexcept>
int main(int argc,char**argv)
{
    if(argc!=2)return 2;
    try
    {
        Nif::NIFFile file(VFS::Path::toNormalized(argv[1]));
        Nif::Reader reader(file,nullptr);
        reader.parse(std::make_unique<std::ifstream>(argv[1],std::ios::binary));
        const auto carried=NifBullet::loadActorRagdollDefinition(Nif::FileView(file));
        const auto ground=NifBullet::loadWeaponReferenceRagdollDefinition(Nif::FileView(file));
        if (carried.mBodies.empty() || ground.mBodies.empty() || !ground.mReferenceRoot
            || ground.mSourceHash.size()!=16 || carried.mSourceHash!=ground.mSourceHash)
            throw std::runtime_error("shield has no identified carried/reference rigid body");
        std::cout << "carried " << carried.mBodies.size() << " ground " << ground.mBodies.size()
                  << " joints " << ground.mJoints.size() << " root "
                  << (ground.mReferenceRoot ? std::to_string(*ground.mReferenceRoot) : "none")
                  << " hash_bytes " << ground.mSourceHash.size() << '\n';
        for(const auto& body:ground.mBodies)
            std::cout << "body " << body.mRecord << " node " << body.mNodeRecord << " mass " << body.mMass
                      << " shape " << body.mShape.index() << " flags " << body.mCollisionFlags << '\n';
    }
    catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
}

